"""Prepare a batch of M/K signals for V3: Gaia cone, selection entry, acquisition, response, staging, checks.

mk_prepare.py BATCH_JSON. BATCH_JSON lists {"signal_id", "mask": [signal ids], "note"}; masked signals are
other independent BOIs on the same source, declared before fitting. Each case goes to mk/cases/<source>-<n>;
cases failing acquisition, aperture authentication, closure (fewer than two quarters) or the capable-source
check get a hold record and are not queued. Prints the queueable case directories in batch order.
mk_prepare.py --resume CASE_DIR... restages acquired cases from the response step (survey cases too).
"""

import json
import math
import os
import subprocess
import sys
from datetime import UTC, datetime
from pathlib import Path

import pandas as pd

W = Path("/Users/adam/Other/spacelab/other/boi-v3-20261025")
PY, APERTURE = str(W / "runtime-v3/bin/python"), "/Users/adam/Other/spacelab/other/boi-repair-20261021/aperture-runtime-v2/bin/python"
TABLES = "/Users/adam/Other/kepler-bonus-exoplanets/results/dwarfs"
SELECTION = W / "mk/mk-selection-20261025.json"
BATCH = None
ENQUEUE = os.environ.get("MK_ENQUEUE") == "1"  # append each ready case to queue-4.json as it is staged


def run(args, log, python=PY):
    with open(log, "w") as stream:
        return subprocess.run([python, "-B", *map(str, args)], stdout=stream, stderr=subprocess.STDOUT, cwd="/Users/adam/Other/spacelab").returncode


def cone(sid, ra, dec):
    q = f"SELECT source_id, ra, dec, pmra, pmdec, phot_g_mean_mag, DISTANCE(POINT(ra,dec), POINT({ra},{dec}))*3600 AS separation_arcsec FROM gaiadr3.gaia_source WHERE 1=CONTAINS(POINT(ra,dec), CIRCLE({ra},{dec},{60 / 3600}))"
    path = W / f"mk/census/{sid}.json"
    if not path.exists():
        subprocess.run(["/usr/bin/curl", "--fail-with-body", "-s", "--max-time", "120", "https://gea.esac.esa.int/tap-server/tap/sync", "--data-urlencode", "REQUEST=doQuery", "--data-urlencode", "LANG=ADQL", "--data-urlencode", "FORMAT=json", "--data-urlencode", f"QUERY={q}", "-o", str(path)], check=True)
    g = json.loads(path.read_text())
    rows = [dict(zip([c["name"] for c in g["metadata"]], x)) for x in g["data"]]
    assert any(str(x["source_id"]) == sid for x in rows), f"{sid} missing from its own cone"
    neighbors = [str(x["source_id"]) for x in sorted(rows, key=lambda x: x["separation_arcsec"]) if str(x["source_id"]) != sid]
    import hashlib

    return neighbors, dict(path=str(path), sha256=hashlib.sha256(path.read_bytes()).hexdigest(), radius_arcsec=60, query=q)


def hold(case, status, reason):
    (case / "batch-hold.json").write_text(json.dumps(dict(utc=datetime.now(UTC).isoformat(), status=status, reason=reason, disposition="REMAINS_PC"), indent=1) + "\n")
    print("HOLD", case.name, status, flush=True)


def prepare(item, bois, coords, selection):
    sig = item["signal_id"]
    sid, n = sig.split("-")[3], sig.split("-")[4]
    r = bois.loc[sig]
    neighbors, census = cone(sid, *coords[sid])
    clock = lambda s: dict(signal_id=s, period_days=float(bois.loc[s, "period_days"]), epoch_bkjd=float(bois.loc[s, "epoch_bkjd"]), duration_days=float(bois.loc[s, "duration_days"]))  # noqa: E731
    selection["signals"][sig] = dict(source_id=sid, kic=None if pd.isna(r.kic) else int(r.kic), rank=len(selection["signals"]) + 1, search_snr=float(r.search_snr), proposal=clock(sig), neighbors=neighbors, other_signals=[clock(s) for s in item["mask"]], census=census)
    selection.setdefault("amendments", []).append(dict(utc=datetime.now(UTC).isoformat(), signal=sig, change=f"{BATCH} (25 October 2026, PI request for a 24-hour V3 queue): {item['note']}"))
    SELECTION.write_text(json.dumps(selection, indent=1) + "\n")
    case = W / f"mk/cases/{sid}-{n}"
    if run([W / "tools/acquire.py", sid, sig, case], W / f"mk/logs/acquire-{sid}-{n}.log") != 0:
        case.mkdir(parents=True, exist_ok=True)
        log = (W / f"mk/logs/acquire-{sid}-{n}.log").read_text()
        # The native prior needs the target's TIC mass and radius; name that failure rather than the aperture.
        status = "HELD_HOST_WITHOUT_TIC_MASS_RADIUS" if 'tic["mass"]' in log else "HELD_NO_NONDUPLICATE_TIC_RECORD" if "tics_target" in log else "HELD_ACQUISITION_OR_APERTURE_AUTHENTICATION"
        return hold(case, status, log[-300:])
    return stage(case)


def stage(case):
    """Everything after acquisition: response, staging, closure, capable sources, reddening and population."""
    if run([W / "tools/response.py", case, case / "scene-preview-v1.csv", case / "geometry-preview-v1.npz", case / "response-v1"], case / "response.log", APERTURE) != 0:
        return hold(case, "HELD_RESPONSE_FAILED", (case / "response.log").read_text()[-300:])
    if run([W / "tools/stage_native.py", case, case, 5], case / "stage-native.log") != 0:
        return hold(case, "HELD_STAGING_FAILED", (case / "stage-native.log").read_text()[-300:])
    passing = json.loads((case / "native-v3/selection.json").read_text())["passing_quarters"]
    if len(passing) < 2:
        return hold(case, "HELD_RESPONSE_CLOSURE_FEWER_THAN_TWO_QUARTERS", f"Passing quarters {passing}")
    return finish_stage(case, passing)


def finish_stage(case, passing):
    """Capable sources, aperture depth, reddening and population of a staged case."""
    sys.path.insert(0, str(W / "tools"))
    import capable_check

    count, missing = capable_check.check(case)
    if missing:
        return hold(case, "HELD_CAPABLE_SOURCE_WITHOUT_STELLAR_PROPERTIES_BEFORE_NATIVE", f"{count} capable sources; missing mass/radius/Teff: {missing}")
    depth = json.loads((case / "native-preparation-review.json").read_text())["measured_aperture_depth"]
    if depth <= 0:
        return hold(case, "HELD_NO_APERTURE_DEPTH", f"Measured raw-aperture depth {depth * 1e6:.1f} ppm at the supplied clock (with any declared masks).")
    tmag = float(pd.read_csv(case / "scene-preview-v1.csv").Tmag.iloc[0])
    ebv = next((x["ebv"] for x in json.loads((case / "stellar-inventory-retained.json").read_text())["rows"][0]["tic_exact_id_matches"] if x.get("ebv") is not None), None)
    if ebv is None:
        return hold(case, "HELD_NO_TIC_REDDENING", "The target's TIC record has no E(B-V) for the field population.")
    limit = math.ceil(tmag - 2.5 * math.log10(depth))
    subprocess.Popen([PY, "-B", str(W / "tools/population.py"), str(case / "scene-preview-v1.csv"), str(ebv), str(limit), str(case / "population-v1")], stdout=open(case / "population.log", "w"), stderr=subprocess.STDOUT, cwd="/Users/adam/Other/spacelab", start_new_session=True)
    print("READY", case, len(passing), "quarters", f"{count} capable", f"maglim {limit}", flush=True)
    if ENQUEUE:
        enqueue(case)
    return case


def enqueue(case, queue=W / "queue-4.json"):
    """Append a ready case to the scheduler queue; the rename is atomic, so the scheduler never reads a partial file."""
    q = json.loads(queue.read_text())
    if str(case) not in q:
        tmp = queue.with_suffix(".tmp")
        tmp.write_text(json.dumps([*q, str(case)], indent=1))
        tmp.replace(queue)


def resume(cases):
    """Restage acquired cases from the response step; an earlier hold record is kept under a superseded name."""
    stamp = datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ")
    ready = []
    for case in map(Path, cases):
        for name in ("batch-hold.json", "response-hold.json", "response.log"):
            if (case / name).exists():
                (case / name).rename(case / name.replace(".", f"-superseded-{stamp}.", 1))
        assert not (case / "response-v1").exists() and not (case / "native-v3").exists(), f"{case} was already staged"
        ready += [c for c in [stage(case.resolve())] if c is not None]
    print(json.dumps([str(c) for c in ready]))


def main(batch):
    global BATCH
    BATCH = Path(batch).stem
    bois = pd.read_csv(W / "mk/bois-20261025.csv", dtype={"source_id": str}).set_index("signal_id")
    coords = json.loads((W / "mk/coords-20261025.json").read_text())
    selection = json.loads(SELECTION.read_text())
    ready = [c for c in (prepare(item, bois, coords, selection) for item in json.loads(Path(batch).read_text())) if c is not None]
    print(json.dumps([str(c) for c in ready]))


if __name__ == "__main__":
    resume(sys.argv[2:]) if sys.argv[1] == "--resume" else main(sys.argv[1])

"""Keep three V3 jobs on the Mac: finish completed native fits, start queued ones.

scheduler.py QUEUE_JSON. QUEUE_JSON lists case directories in priority order. A case
whose native log ends with "done" gets tools/finish_case.py (declared acceptance rules,
then its campaign); a case without a native log starts its fit when a slot is free.
Marker files make every action happen once. Writes scheduler-status.json every cycle.
A slots.json beside the queue ({"slots": N}) overrides the default budget while CPU is shared. Beyond two jobs, a new
one starts only when measured CPU idle time (top, two one-second samples) leaves at least three of the Mac's cores idle
and three minutes have passed since the last start (Adam, 26 October 2026: use the full hardware). Idle cores then fill;
a five-thread start can oversubscribe by at most two threads, only while every running job is at full parallelism.
"""

import json
import os
import subprocess
import sys
import time
from datetime import UTC, datetime
from pathlib import Path

PYTHON = "/Users/adam/Other/spacelab/other/boi-v3-20261025/runtime-v3/bin/python"
TOOLS = Path(__file__).resolve().parent
SLOTS, CPU = 3, 5


def running(pattern):
    out = subprocess.run(["pgrep", "-f", pattern], capture_output=True, text=True).stdout.split()
    return len(out)


def slots(root):
    path = root / "slots.json"
    return json.loads(path.read_text())["slots"] if path.exists() else SLOTS


def idle_cores():
    line = [x for x in subprocess.run(["top", "-l", "2", "-n", "0", "-s", "1"], capture_output=True, text=True).stdout.splitlines() if x.startswith("CPU usage")][-1]
    return float(line.split(",")[-1].split("%")[0]) / 100 * os.cpu_count()


def room(busy, root, last_start):
    if busy >= slots(root):
        return False
    return busy < 2 or (time.time() - last_start >= 180 and idle_cores() >= CPU - 2)


def native_done(case):
    log = case / "native-v3/native.log"
    return log.exists() and "\ndone 20" in log.read_text(errors="replace")


def native_failed(case):
    log = case / "native-v3/native.log"
    return log.exists() and "Traceback" in log.read_text(errors="replace")


def main(queue_path):
    root = queue_path.parent
    last_start = 0.0
    while True:
        queue = [Path(p) for p in json.loads(queue_path.read_text())]
        status = []
        for case in queue:
            native = case / "native-v3"
            if native_done(case) and not (native / "finish.started").exists():
                (native / "finish.started").write_text(datetime.now(UTC).isoformat())
                with (native / "finish.log").open("w") as log:
                    subprocess.run([PYTHON, "-B", str(TOOLS / "finish_case.py"), str(case), str(CPU), "--launch"], stdout=log, stderr=subprocess.STDOUT, cwd="/Users/adam/Other/spacelab")
            state = "finished" if (native / "finish.started").exists() else "failed" if native_failed(case) else "native-running" if (native / "native.log").exists() else "queued"
            status.append(dict(case=str(case), state=state))
        # The wrappers start before their Python stages, so a campaign that finish_case has just launched is counted.
        busy = running("^/bin/bash .*/run_(native|campaign).sh")
        for item in status:
            if item["state"] != "queued":
                continue
            if not room(busy, root, last_start):
                break  # Queue order: a later case never starts ahead of the first waiting one
            case = Path(item["case"])
            log = case / "native-v3/native.log"
            subprocess.Popen(["nohup", "caffeinate", "-i", str(TOOLS / "run_native.sh"), str(case / "native-v3")], stdout=log.open("w"), stderr=subprocess.STDOUT, cwd="/Users/adam/Other/spacelab", start_new_session=True)
            item["state"] = "native-started"
            busy += 1
            last_start = time.time()
        (root / "scheduler-status.json").write_text(json.dumps(dict(utc=datetime.now(UTC).isoformat(), busy=busy, cases=status), indent=1))
        if all(i["state"] in ("finished", "failed") for i in status) and busy == 0:
            return
        time.sleep(60)


if __name__ == "__main__":
    main(Path(sys.argv[1]).resolve())
